cd /workspace/pnpm && python3 - <<'EOF'
import json, glob, os, collections

pkgs = {}  # name -> (dir, deps set of workspace deps)
for pj in glob.glob('*/*/package.json') + glob.glob('*/package.json'):
    if 'node_modules' in pj: continue
    try:
        d = json.load(open(pj))
    except Exception: continue
    name = d.get('name')
    if not name: continue
    deps = set()
    for sec in ('dependencies','devDependencies','optionalDependencies','peerDependencies'):
        for k,v in (d.get(sec) or {}).items():
            if isinstance(v,str) and v.startswith('workspace:'):
                deps.add((k, sec))
    pkgs[name] = (os.path.dirname(pj), deps)

# reverse graph
rev = collections.defaultdict(set)  # dep -> set of (dependent, section)
for name,(dir_,deps) in pkgs.items():
    for (dep,sec) in deps:
        rev[dep].add((name,sec))

targets = ['@pnpm/constants','@pnpm/dependency-path']
for t in targets:
    print(f"\n=== Direct dependents of {t} ===")
    for (n,sec) in sorted(rev[t]):
        if n==t: continue
        print(f"  {n} ({sec}) -> {pkgs[n][0]}")

# transitive closure
def closure(t):
    seen=set()
    frontier={t}
    while frontier:
        nxt=set()
        for f in frontier:
            for (n,sec) in rev[f]:
                if n not in seen and n!=t:
                    seen.add(n); nxt.add(n)
        frontier=nxt
    return seen

for t in targets:
    c = closure(t)
    print(f"\n=== Transitive dependents of {t}: {len(c)} ===")
    for n in sorted(c): print(f"  {n} -> {pkgs[n][0]}")

print(f"\nTotal workspace packages: {len(pkgs)}")
EOF

