pkgs = {}
for pj in glob.glob('*/*/package.json') + glob.glob('*/package.json'):
    if 'node_modules' in pj: continue
    try: d = json.load(open(pj))
    except Exception: continue
    name = d.get('name')
    if not name: continue
    deps = {}
    for sec in ('dependencies','optionalDependencies','peerDependencies'):
        for k,v in (d.get(sec) or {}).items():
            if isinstance(v,str) and v.startswith('workspace:'): deps[k]='prod'
    for k,v in (d.get('devDependencies') or {}).items():
        if isinstance(v,str) and v.startswith('workspace:') and k not in deps: deps[k]='dev'
    pkgs[name] = {'dir': os.path.dirname(pj), 'deps': deps}

rev = collections.defaultdict(list)
for name,info in pkgs.items():
    for dep,sec in info['deps'].items():
        rev[dep].append((name,sec))

TARGETS = ['@pnpm/constants','@pnpm/dependency-path']

def closure(t):
    seen={}
    frontier=[t]
    while frontier:
        nxt=[]
        for f in frontier:
            for (n,sec) in rev[f]:
                if n in seen or n==t: continue
                seen[n] = 'direct' if f==t else 'transitive'
                nxt.append(n)
        frontier=nxt
    return seen

cl = {t: closure(t) for t in TARGETS}
union = sorted(set(cl[TARGETS[0]]) | set(cl[TARGETS[1]]) | set(TARGETS))

out = {}
for n in union:
    info = pkgs[n]
    d = info['dir']
    rec = {'dir': d}
    for t in TARGETS:
        key = t.split('/')[1]
        if n == t: rec[key] = 'SELF'
        elif n in cl[t]:
            reach = cl[t][n]
            sec = info['deps'].get(t)
            rec[key] = f"{reach}{'-'+sec if sec else ''}"
        else: rec[key] = '-'
    # does src import the targets / use lockfileVersion?
    src = os.path.join(d,'src')
    def g(pattern, path):
        try:
            r = subprocess.run(['grep','-rl',pattern,path], capture_output=True, text=True)
            return bool(r.stdout.strip())
        except Exception: return False
    rec['src_uses_deppath'] = g("@pnpm/dependency-path", src) if os.path.isdir(src) else False
    rec['src_uses_constants'] = g("@pnpm/constants", src) if os.path.isdir(src) else False
    rec['src_lockfile_version'] = g("lockfileVersion", src) if os.path.isdir(src) else False
    test_dirs = [p for p in (os.path.join(d,'test'),) if os.path.isdir(p)]
    rec['test_uses'] = any(g("@pnpm/dependency-path", p) or g("LOCKFILE_VERSION", p) or g("lockfileVersion", p) for p in test_dirs)
    out[n] = rec

print(json.dumps(out, indent=1))
print(f"\nUNION COUNT (incl. the 2 changed): {len(union)}")
EOF
